"""Summarize a CSV with header category,amount,status — paid rows only."""

import csv
import json
import sys
from decimal import Decimal, ROUND_HALF_UP

def summarize(input_filename: str) -> str:
    totals: dict[str, Decimal] = {}

    with open(input_filename, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            status = (row.get("status") or "").strip().casefold()
            if status != "paid":
                continue

            cat_raw = row.get("category") or ""
            cat_norm = " ".join(cat_raw.split()).casefold()
            if cat_norm == "":
                cat_norm = "uncategorized"

            amt = Decimal(row.get("amount", "0").strip())
            amt_rounded = amt.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

            totals[cat_norm] = totals.get(cat_norm, Decimal("0")) + amt_rounded

    sorted_cats = sorted(totals.keys())
    categories = [
        {"category": name, "total": f"{totals[name]:.2f}"}
        for name in sorted_cats
    ]
    grand_total = sum(totals.values(), Decimal("0"))

    result = {"categories": categories, "total": f"{grand_total:.2f}"}
    return json.dumps(result)


def main() -> None:
    if len(sys.argv) < 2:
        print("Usage: solution.py <input.csv>", file=sys.stderr)
        sys.exit(1)
    print(summarize(sys.argv[1]))


if __name__ == "__main__":
    main()"}

